<script setup>
import {computed,onMounted,ref} from 'vue';import {del,fmt,get,pct,post,put} from '../api/client';import DataTable from '../components/DataTable.vue';import MetricCard from '../components/MetricCard.vue';import StockHistoryModal from '../components/StockHistoryModal.vue';
const tab=ref('model'),runs=ref([]),selected=ref(''),data=ref({counts:{},items:[],rules:{}}),positions=ref([]),loading=ref(false),historyStock=ref(null),statusFilter=ref(''),positionForm=ref(null),message=ref('');
const visibleRows=computed(()=>statusFilter.value?data.value.items.filter(row=>row.status_level===statusFilter.value):data.value.items),openPositions=computed(()=>positions.value.filter(row=>row.status==='open')),totalValue=computed(()=>openPositions.value.reduce((sum,row)=>sum+Number(row.market_value||0),0)),totalProfit=computed(()=>positions.value.reduce((sum,row)=>sum+Number(row.profit_amount||0),0));
async function load(){if(!selected.value)return;loading.value=true;try{data.value=await get(`/tracking/${selected.value}`)}finally{loading.value=false}}
async function loadPositions(){positions.value=await get('/tracking/positions')}
async function switchTab(value){tab.value=value;message.value='';if(value==='actual')await loadPositions()}
function openPosition(row=null){tab.value='actual';positionForm.value={id:null,stock_code:row?.stock_code||'',buy_date:row?.entry_date||new Date().toLocaleDateString('en-CA'),buy_price:row?.entry_price||'',quantity:100,status:'open',sell_date:null,sell_price:null,note:'',source_candidate_id:row?.candidate_id||null}}
function editPosition(row){positionForm.value={id:row.id,stock_code:row.stock_code,buy_date:row.buy_date,buy_price:row.buy_price,quantity:row.quantity,status:row.status,sell_date:row.sell_date,sell_price:row.sell_price,note:row.note||'',source_candidate_id:row.source_candidate_id}}
async function savePosition(){message.value='';try{const body={...positionForm.value};delete body.id;if(body.status==='open'){body.sell_date=null;body.sell_price=null}if(positionForm.value.id)await put(`/tracking/positions/${positionForm.value.id}`,body);else await post('/tracking/positions',body);positionForm.value=null;message.value='持仓记录已保存';await loadPositions()}catch(e){message.value=e.message}}
async function removePosition(row){if(!confirm(`确认删除 ${row.stock_code} 的持仓记录？`))return;try{await del(`/tracking/positions/${row.id}`);message.value='持仓记录已删除';await loadPositions()}catch(e){message.value=e.message}}
onMounted(async()=>{runs.value=await get('/tracking');selected.value=runs.value[0]?.id||'';await Promise.all([load(),loadPositions()])});
const statusClass=(v,r)=>`tracking-status status-${r.status_level}`;
const modelColumns=[{label:'代码',key:'stock_code',action:r=>historyStock.value=r},{label:'名称',key:'stock_name'},{label:'排名',key:'ranking'},{label:'模拟买入日',key:'entry_date'},{label:'模拟买入价',key:'entry_price',format:v=>fmt(v,2)},{label:'当前价',key:'current_price',format:v=>fmt(v,2)},{label:'当前收益',key:'current_return',format:pct,class:v=>v==null?'':v>=0?'positive':'negative'},{label:'最高收益',key:'highest_return',format:pct},{label:'高点回撤',key:'drawdown',format:pct},{label:'模型目标价',key:'target_price',format:v=>fmt(v,2)},{label:'波动风险价',key:'risk_price',format:v=>fmt(v,2)},{label:'可卖日期',key:'sellable_date'},{label:'状态',key:'status',class:statusClass},{label:'触发原因',key:'reason'},{label:'操作',key:'position_action',format:()=> '加入持仓',action:openPosition,sortable:false}];
const positionColumns=[{label:'代码',key:'stock_code',action:r=>historyStock.value=r},{label:'名称',key:'stock_name'},{label:'买入日',key:'buy_date'},{label:'买入价',key:'buy_price',format:v=>fmt(v,2)},{label:'数量',key:'quantity',format:v=>fmt(v,0)},{label:'估值/卖出价',key:'valuation_price',format:v=>fmt(v,2)},{label:'收益率',key:'return_rate',format:pct,class:v=>v==null?'':v>=0?'positive':'negative'},{label:'盈亏金额',key:'profit_amount',format:v=>fmt(v,2),class:v=>v==null?'':v>=0?'positive':'negative'},{label:'市值',key:'market_value',format:v=>fmt(v,2)},{label:'状态',key:'status',format:v=>v==='open'?'持有中':'已平仓'},{label:'备注',key:'note'},{label:'操作',key:'edit_action',format:()=> '编辑/平仓',action:editPosition,sortable:false}];
</script>
<template><div class="model-tabs tracking-tabs"><button :class="{active:tab==='model'}" @click="switchTab('model')">模型自动跟踪</button><button :class="{active:tab==='actual'}" @click="switchTab('actual')">我的实际持仓</button></div><p v-if="message" class="notice">{{message}}</p><template v-if="tab==='model'"><div class="tracking-toolbar card"><div><h2>T+1 自动模拟跟踪</h2><p>仅跟踪 T+1 可交易模型 Top30；不代表真实持仓或确定性交易建议。</p></div><select v-if="runs.length" v-model="selected" @change="load"><option v-for="run in runs" :key="run.id" :value="run.id">信号日 {{run.base_date}} · Top{{run.candidate_count}}</option></select></div><div v-if="!runs.length" class="empty">暂无 T+1 可交易模型预测批次</div><template v-else><div class="tracking-rules"><b>执行口径</b><span>{{data.rules.entry}}</span><span>{{data.rules.sellable}}</span><span>风险价：{{data.rules.risk}}</span><span>最长持有：{{data.rules.max_holding_days}} 个交易日</span></div><div class="grid tracking-metrics"><MetricCard label="等待/买入日" :value="(data.counts.waiting||0)+(data.counts.observe||0)" sub="尚不可执行卖出"/><MetricCard label="继续持有" :value="data.counts.hold||0" sub="未触发退出条件"/><MetricCard label="注意/止盈" :value="(data.counts.warning||0)+(data.counts.take_profit||0)" sub="需要重点观察"/><MetricCard label="建议退出" :value="data.counts.exit||0" sub="风险或持有期触发"/></div><div class="section-heading section"><div><h2>跟踪明细</h2><span>{{data.observed_at?`最新盘中快照 ${data.observed_at}`:'使用最新收盘日线'}}</span></div><select v-model="statusFilter"><option value="">全部状态</option><option value="waiting">等待买入</option><option value="observe">买入日观察</option><option value="hold">继续持有</option><option value="warning">注意回撤</option><option value="take_profit">建议止盈</option><option value="exit">建议退出/到期</option></select></div><div v-if="loading" class="empty">正在计算跟踪状态…</div><DataTable v-else :columns="modelColumns" :rows="visibleRows" default-sort="ranking"/><p class="tracking-disclaimer">自动跟踪按标准化模拟价格计算，未计手续费、滑点、涨跌停、停牌及实际成交差异；状态用于研究退出规则，不构成投资建议。</p></template></template><template v-else><div class="section-heading"><div><h2>我的实际持仓</h2><span>仅当前登录账号可见 · 按实际成交信息计算</span></div><button class="primary-button" @click="openPosition()">新增持仓</button></div><div class="grid tracking-metrics"><MetricCard label="持有数量" :value="openPositions.length" sub="当前未平仓记录"/><MetricCard label="当前持仓市值" :value="fmt(totalValue,2)" sub="按最新收盘价估值"/><MetricCard label="累计浮动/实现盈亏" :value="fmt(totalProfit,2)" sub="未扣手续费与滑点"/><MetricCard label="全部记录" :value="positions.length" sub="包含历史已平仓"/></div><div v-if="positionForm" class="card position-editor"><div class="detail-heading"><h2>{{positionForm.id?'编辑持仓/平仓':'新增实际持仓'}}</h2><button @click="positionForm=null">关闭</button></div><div class="editor-grid"><label>股票代码<input v-model="positionForm.stock_code" maxlength="6"></label><label>买入日期<input v-model="positionForm.buy_date" type="date"></label><label>实际买入价<input v-model.number="positionForm.buy_price" type="number" min="0.0001" step="0.01"></label><label>持仓数量<input v-model.number="positionForm.quantity" type="number" min="0.0001" step="100"></label><label>状态<select v-model="positionForm.status"><option value="open">持有中</option><option value="closed">已平仓</option></select></label><label v-if="positionForm.status==='closed'">卖出日期<input v-model="positionForm.sell_date" type="date"></label><label v-if="positionForm.status==='closed'">实际卖出价<input v-model.number="positionForm.sell_price" type="number" min="0.0001" step="0.01"></label><label>备注<input v-model="positionForm.note" maxlength="500"></label></div><div class="position-actions"><button class="primary-button" @click="savePosition">保存</button><button v-if="positionForm.id" class="danger-button" @click="removePosition(positionForm)">删除记录</button></div></div><div class="section"><DataTable :columns="positionColumns" :rows="positions" default-sort="buy_date" :default-direction="-1"/></div><p class="tracking-disclaimer">实际持仓由用户手工记录，系统不会连接券商或自动交易；当前未平仓记录使用最新收盘日线估值。</p></template><StockHistoryModal :stock="historyStock" model-code="tradeable_t1_open" @close="historyStock=null"/></template>